interface Billable{
    abstract double units();
    abstract double unitRate();
    abstract double fixedCharge();}


    double energyCharge(double units, double unitRate){
        return units*unitRate;
    }
    double totalBill(double energyCharge, double fixedCharge){
        return energyCharge+fixedCharge;
    }

    void printBill(){
        double ener= energyCharge(units, unitRate);
        double totb = totalBill(ener, fixedCharge);
        System.out.printf("Energy Charge = %.2f", ener);
        System.out.printf("Fixed Charge = %.2f", fixedCharge);
        System.out.printf("Total Bill = %.2f", totb);

    }


class DomesticConnection implements Billable {
    private double units;

    DomesticConnection(double units){
        this.units = units;
    }

    @Override
    public double units(){
        return units;
    }

    @Override
    public double unitRate(){
        return 5.0;
    }

    @Override public double fixedCharge(){
        return 50.0;
    }
}

whats wrong with my code?

